140	// admin returns a client authenticated as the admin account.
141	func (b liveBench) admin(t *testing.T) *client {
142		t.Helper()
143		requireBench(t)
144		c := newClient(b.restURL, adminUserID, b.secrets.AdminPassword)
145		t.Cleanup(c.closeIdle)
146		return c
147	}
148	
149	// anonymous returns a client that sends no credentials.
150	func (b liveBench) anonymous(t *testing.T) *client {
151		t.Helper()
152		requireBench(t)
153		c := newClient(b.restURL, "", "")
154		t.Cleanup(c.closeIdle)
155		return c
156	}
