158	// puller returns a client authenticated as the read-only account.
159	func (b liveBench) puller(t *testing.T) *client {
160		t.Helper()
161		requireBench(t)
162		if b.secrets.PullPassword == "" {
163			t.Fatalf("no %s password in the secrets file: provision the bench with `mise run nexus-bench:provision`", pullUserID)
164		}
165		c := newClient(b.restURL, pullUserID, b.secrets.PullPassword)
166		t.Cleanup(c.closeIdle)
167		return c
168	}
