170	// liveRepository is one entry of GET /service/rest/v1/repositories.
171	type liveRepository struct {
172		Name   string `json:"name"`
173		Format string `json:"format"`
174		Type   string `json:"type"`
175	}
176	
177	// liveGroup and liveProxy hold the one field of a repository the tests compare.
178	type liveGroup struct {
179		Group struct {
180			MemberNames []string `json:"memberNames"`
181		} `json:"group"`
182	}
183	
184	type liveProxy struct {
185		Proxy struct {
186			RemoteURL string `json:"remoteUrl"`
187		} `json:"proxy"`
188	}
