190	func TestIntegrationBenchDescribed(t *testing.T) {
191		requireBench(t)
192		b := openLiveBench(t)
193		ctx, cancel := context.WithTimeout(context.Background(), liveCallTimeout)
194		defer cancel()
195	
196		t.Run("the REST status answers 200 on the loopback URL", func(t *testing.T) {
197			resp, err := b.anonymous(t).do(ctx, request{op: "read the Nexus status", method: http.MethodGet, path: restStatusPath})
198			if err != nil {
199				t.Fatalf("GET %s: %v", restStatusPath, err)
200			}
201			if resp.status != http.StatusOK {
202				t.Errorf("GET %s = HTTP %d, want 200", restStatusPath, resp.status)
203			}
204		})
205	
206		admin := b.admin(t)
207		var listed []liveRepository
208		if err := admin.read(ctx, "list the repositories", restAPI+"/repositories", nil, &listed); err != nil {
209			t.Fatalf("list the repositories: %v", err)
210		}
211	
212		for _, want := range b.desc.Repositories {
213			t.Run("repository "+want.Name, func(t *testing.T) {
214				i := slices.IndexFunc(listed, func(r liveRepository) bool { return r.Name == want.Name })
215				if i < 0 {
216					t.Fatalf("repository %s is not on the instance", want.Name)
217				}
218				if got := listed[i]; got.Type != want.Type || got.Format != "docker" {
219					t.Errorf("repository %s is %s/%s, want docker/%s", want.Name, got.Format, got.Type, want.Type)
220				}
221				path := dockerReposPath + "/" + want.Type + "/" + want.Name
222				switch want.Type {
223				case "group":
224					var g liveGroup
225					if err := admin.read(ctx, "read the group "+want.Name, path, nil, &g); err != nil {
226						t.Fatal(err)
227					}
228					got, members := slices.Clone(g.Group.MemberNames), slices.Clone(want.Members)
229					slices.Sort(got)
230					slices.Sort(members)
231					if !slices.Equal(got, members) {
232						t.Errorf("members of %s = %v, want %v", want.Name, got, members)
233					}
234				case "proxy":
235					var p liveProxy
236					if err := admin.read(ctx, "read the proxy "+want.Name, path, nil, &p); err != nil {
237						t.Fatal(err)
238					}
239					if p.Proxy.RemoteURL != want.RemoteURL {
240						t.Errorf("remote URL of %s = %q, want %q", want.Name, p.Proxy.RemoteURL, want.RemoteURL)
241					}
242				}
243			})
244		}
245	}
