247	func TestIntegrationPullAccountIsReadOnly(t *testing.T) {
248		requireBench(t)
249		b := openLiveBench(t)
250		ctx, cancel := context.WithTimeout(context.Background(), liveCallTimeout)
251		defer cancel()
252		pull := b.puller(t)
253	
254		t.Run("it reads the repositories", func(t *testing.T) {
255			resp, err := pull.do(ctx, request{op: "list the repositories as " + pullUserID, method: http.MethodGet, path: restAPI + "/repositories"})
256			if err != nil {
257				t.Fatal(err)
258			}
259			if resp.status != http.StatusOK {
260				t.Errorf("GET /repositories as %s = HTTP %d, want 200", pullUserID, resp.status)
261			}
262		})
263	
264		t.Run("it cannot create a repository", func(t *testing.T) {
265			body, err := json.Marshal(map[string]any{
266				"name": readOnlyProbeRepository, "online": true,
267				"storage": map[string]any{"blobStoreName": defaultBlobStore, "strictContentTypeValidation": true, "writePolicy": "ALLOW"},
268				"docker":  map[string]any{"v1Enabled": false, "forceBasicAuth": false},
269			})
270			if err != nil {
271				t.Fatal(err)
272			}
273			resp, err := pull.do(ctx, request{
274				op: "create a repository as " + pullUserID, method: http.MethodPost,
275				path: dockerReposPath + "/hosted", contentType: "application/json", body: body,
276			})
277			if err != nil {
278				t.Fatal(err)
279			}
280			if resp.status >= 200 && resp.status <= 299 {
281				// The account can write: remove what it made, then fail.
282				cleanup := b.admin(t)
283				_, delErr := cleanup.expect(ctx, request{op: "delete the probe repository", method: http.MethodDelete, path: restAPI + "/repositories/" + readOnlyProbeRepository})
284				t.Fatalf("POST a repository as %s = HTTP %d, want 403; the probe repository was deleted again (error: %v)", pullUserID, resp.status, delErr)
285			}
286			if resp.status != http.StatusForbidden {
287				t.Errorf("POST a repository as %s = HTTP %d, want 403", pullUserID, resp.status)
288			}
289		})
290	}
