292	func TestIntegrationAnonymousAsDescribed(t *testing.T) {
293		requireBench(t)
294		b := openLiveBench(t)
295		ctx, cancel := context.WithTimeout(context.Background(), liveCallTimeout)
296		defer cancel()
297	
298		i := slices.IndexFunc(b.desc.Accounts, func(a DescriptorAccount) bool { return a.UserID == anonymousUser })
299		if i < 0 || b.desc.Accounts[i].Enabled == nil {
300			t.Fatal("the descriptor does not say whether anonymous access is enabled")
301		}
302		enabled := *b.desc.Accounts[i].Enabled
303	
304		t.Run("the instance setting", func(t *testing.T) {
305			var got struct {
306				Enabled bool   `json:"enabled"`
307				UserID  string `json:"userId"`
308			}
309			if err := b.admin(t).read(ctx, "read the anonymous access", anonymousPath, nil, &got); err != nil {
310				t.Fatal(err)
311			}
312			if got.Enabled != enabled {
313				t.Errorf("anonymous access enabled = %v, the descriptor says %v", got.Enabled, enabled)
314			}
315		})
316	
317		// Without credentials the repository list is answered when anonymous access
318		// is on and refused when it is off (hypothesis H-REST, first run at step 10).
319		t.Run("what a request without credentials gets", func(t *testing.T) {
320			want := http.StatusUnauthorized
321			if enabled {
322				want = http.StatusOK
323			}
324			resp, err := b.anonymous(t).do(ctx, request{op: "list the repositories anonymously", method: http.MethodGet, path: restAPI + "/repositories"})
325			if err != nil {
326				t.Fatal(err)
327			}
328			if resp.status != want {
329				t.Errorf("GET /repositories without credentials = HTTP %d, want %d (anonymous enabled: %v)", resp.status, want, enabled)
330			}
331		})
332	}
