334	// ---- the data set --------------------------------------------------------------
335	
336	// datasetKey is how a listing and the descriptor name an image tag.
337	func datasetKey(name, tag string) string { return name + ":" + tag }
338	
339	// indexComponents maps "name:tag" to the component a listing holds.
340	func indexComponents(list []component) map[string]component {
341		out := make(map[string]component, len(list))
342		for _, c := range list {
343			out[datasetKey(c.Name, c.Version)] = c
344		}
345		return out
346	}
347	
348	// inspectThroughNexus reads the manifest digest of an image with skopeo, by the
349	// path of its repository, as the pull account. It is the fallback of a listing
350	// that gives no digest, and it refuses to ask for what the bench keeps out of
351	// the proxy: reading mirror/uncached through docker-proxy would cache it (F9).
352	func inspectThroughNexus(ctx context.Context, t *testing.T, b liveBench, repository string, img DescriptorImage) string {
353		t.Helper()
354		requireBench(t)
355		if img.Location != string(LocationHosted) && !img.CachedInProxy {
356			t.Fatalf("refusing to read %s through %s: it would cache it", datasetKey(img.Name, img.Tag), repository)
357		}
358		if b.secrets.PullPassword == "" {
359			t.Fatalf("no %s password in the secrets file: provision the bench with `mise run nexus-bench:provision`", pullUserID)
360		}
361		copier, err := NewSkopeoCopier()
362		if err != nil {
363			t.Fatalf("the REST listing gives no digest for %s and skopeo is not usable: %v", datasetKey(img.Name, img.Tag), err)
364		}
365		ref := nexusImageRef(Params{HTTPNodePort: b.desc.REST.NodePort}, repository, DatasetImage{Name: img.Name, Tag: img.Tag})
366		digest, err := copier.ManifestDigest(ctx, ref, &Credentials{User: pullUserID, Password: REDACTED
367		if err != nil {
368			t.Fatalf("read the manifest of %s in %s: %v", datasetKey(img.Name, img.Tag), repository, err)
369		}
370		return digest
371	}
372	
373	// TestIntegrationDatasetAsDescribed checks, read only, that the bench holds the
374	// data set its descriptor lists: every hosted image and every image the proxy
375	// has cached carries the digest of the descriptor, the image the proxy has never
376	// been asked for is not in docker-proxy, and docker-proxy points at the upstream
377	// of the descriptor and is a member of docker-group (the report of NX-01).
378	func TestIntegrationDatasetAsDescribed(t *testing.T) {
379		requireBench(t)
380		b := openLiveBench(t)
381		if len(b.desc.Dataset) == 0 {
382			t.Fatal("the descriptor lists no data set: run `mise run nexus-bench:up` or `mise run nexus-bench:seed` first")
383		}
384		ctx, cancel := context.WithTimeout(context.Background(), liveCallTimeout)
385		defer cancel()
386		admin := b.admin(t)
387	
388		hosted, err := admin.listComponents(ctx, dockerHostedRepository)
389		if err != nil {
390			t.Fatalf("list the components of %s: %v", dockerHostedRepository, err)
391		}
392		proxied, err := admin.listComponents(ctx, dockerProxyRepository)
393		if err != nil {
394			t.Fatalf("list the components of %s: %v", dockerProxyRepository, err)
395		}
396		inHosted, inProxy := indexComponents(hosted), indexComponents(proxied)
397	
398		for _, img := range b.desc.Dataset {
399			key := datasetKey(img.Name, img.Tag)
400			switch {
401			case img.Location == string(LocationHosted):
402				t.Run("hosted "+key, func(t *testing.T) {
403					c, ok := inHosted[key]
404					if !ok {
405						t.Fatalf("%s is not in %s", key, dockerHostedRepository)
406					}
407					got := c.Digest
408					if got == "" {
409						got = inspectThroughNexus(ctx, t, b, dockerHostedRepository, img)
410					}
411					if got != img.Digest {
412						t.Errorf("digest of %s in %s = %s, the descriptor says %s", key, dockerHostedRepository, got, img.Digest)
413					}
414				})
415			case img.CachedInProxy:
416				t.Run("cached "+key, func(t *testing.T) {
417					c, ok := inProxy[key]
418					if !ok {
419						t.Fatalf("%s is not in %s: the seed pulls it through the proxy once", key, dockerProxyRepository)
420					}
421					got := c.Digest
422					if got == "" {
423						got = inspectThroughNexus(ctx, t, b, dockerProxyRepository, img)
424					}
425					if got != img.Digest {
426						t.Errorf("digest of %s in %s = %s, the descriptor says %s", key, dockerProxyRepository, got, img.Digest)
427					}
428				})
429			default:
430				// Read by the REST listing only: a pull through the proxy or the group
431				// would cache it (F9).
432				t.Run("uncached "+key, func(t *testing.T) {
433					if _, ok := inProxy[key]; ok {
434						t.Errorf("%s is in %s although no one asked the proxy for it: run `mise run nexus-bench:reset`", key, dockerProxyRepository)
435					}
436				})
437			}
438		}
439	
440		t.Run("the proxy and the group", func(t *testing.T) {
441			var wantProxy *DescriptorRepository
442			for i, r := range b.desc.Repositories {
443				if r.Name == dockerProxyRepository {
444					wantProxy = &b.desc.Repositories[i]
445				}
446			}
447			if wantProxy == nil {
448				t.Fatalf("the descriptor lists no %s: the proxy is created since NX-02, run `mise run nexus-bench:up`", dockerProxyRepository)
449			}
450			var proxy liveProxy
451			if err := admin.read(ctx, "read the proxy "+dockerProxyRepository, dockerReposPath+"/proxy/"+dockerProxyRepository, nil, &proxy); err != nil {
452				t.Fatalf("%s does not exist on the instance: %v", dockerProxyRepository, err)
453			}
454			if proxy.Proxy.RemoteURL != wantProxy.RemoteURL {
455				t.Errorf("remote URL of %s = %q, the descriptor says %q", dockerProxyRepository, proxy.Proxy.RemoteURL, wantProxy.RemoteURL)
456			}
457			var group liveGroup
458			if err := admin.read(ctx, "read the group "+dockerGroupRepository, dockerReposPath+"/group/"+dockerGroupRepository, nil, &group); err != nil {
459				t.Fatal(err)
460			}
461			for _, member := range []string{dockerHostedRepository, dockerProxyRepository} {
462				if !slices.Contains(group.Group.MemberNames, member) {
463					t.Errorf("%s is not a member of %s (members: %v)", member, dockerGroupRepository, group.Group.MemberNames)
464				}
465			}
466		})
467	}
