469	// ---- lifecycle --------------------------------------------------------------
470	
471	// logWriter sends what the bench prints to the test log, line by line.
472	type logWriter struct{ t *testing.T }
473	
474	func (w logWriter) Write(p []byte) (int, error) {
475		w.t.Helper()
476		for _, line := range strings.Split(strings.TrimRight(string(p), "\n"), "\n") {
477			w.t.Log(line)
478		}
479		return len(p), nil
480	}
