482	// benchSnapshot is what has to be identical after a second up and provision.
483	type benchSnapshot struct {
484		Repositories []string
485		Roles        []string
486		Users        []string
487		// Hosted and Proxy are the components of docker-hosted and docker-proxy,
488		// "name:tag@digest", sorted (DEVDESK-505: a second up leaves them alone).
489		Hosted []string
490		Proxy  []string
491	}
492	
493	// snapshotBench lists repositories, roles and users as admin, sorted.
494	func snapshotBench(ctx context.Context, t *testing.T, c *client) benchSnapshot {
495		t.Helper()
496		names := func(op, path, field string) []string {
497			var rows []map[string]any
498			if err := c.read(ctx, op, path, nil, &rows); err != nil {
499				t.Fatalf("%s: %v", op, err)
500			}
501			out := make([]string, 0, len(rows))
502			for _, row := range rows {
503				s, _ := row[field].(string)
504				out = append(out, s)
505			}
506			slices.Sort(out)
507			return out
508		}
509		images := func(repo string) []string {
510			list, err := c.listComponents(ctx, repo)
511			if err != nil {
512				t.Fatalf("list the components of %s: %v", repo, err)
513			}
514			out := make([]string, 0, len(list))
515			for _, comp := range list {
516				out = append(out, datasetKey(comp.Name, comp.Version)+"@"+comp.Digest)
517			}
518			slices.Sort(out)
519			return out
520		}
521		return benchSnapshot{
522			Repositories: names("list the repositories", restAPI+"/repositories", "name"),
523			Roles:        names("list the roles", rolesPath, "id"),
524			Users:        names("list the users", usersPath, "userId"),
525			Hosted:       images(dockerHostedRepository),
526			Proxy:        images(dockerProxyRepository),
527		}
528	}
