530	func TestIntegrationLifecycle(t *testing.T) {
531		requireBench(t)
532		if os.Getenv(benchLifecycleEnv) != "1" {
533			t.Skipf("set %s=1 as well to run the destructive lifecycle (it deletes the bench namespace)", benchLifecycleEnv)
534		}
535	
536		p, err := FromEnv(Defaults(), os.Getenv)
537		if err != nil {
538			t.Fatalf("parameters: %v", err)
539		}
540		if !p.AcceptEULA {
541			t.Fatalf("the lifecycle provisions Nexus, which needs the EULA accepted: read it, then set %s=yes", envAcceptEULA)
542		}
543		if deadline, ok := t.Deadline(); ok && time.Until(deadline) < lifecycleMinTimeout {
544			t.Fatalf("go test stops this run in %s; the lifecycle needs at least %s: rerun with -timeout 60m", time.Until(deadline).Round(time.Second), lifecycleMinTimeout)
545		}
546		if err := p.Validate(); err != nil {
547			t.Fatalf("parameters: %v", err)
548		}
549	
550		secretsPath := p.SecretsPath
551		if secretsPath == "" {
552			secretsPath = secretsPathFor(t, p.Context, p.Namespace)
553		}
554		runner, err := NewExecRunner(p.Context)
555		if err != nil {
556			t.Fatalf("NewExecRunner: %v", err)
557		}
558		store, err := NewFileStore(secretsPath)
559		if err != nil {
560			t.Fatalf("NewFileStore: %v", err)
561		}
562		if !p.UpstreamIsBench() {
563			t.Fatalf("the lifecycle seeds the bench upstream: unset %s", envUpstreamURL)
564		}
565		if _, err := exec.LookPath("skopeo"); err != nil {
566			t.Fatalf("the lifecycle seeds the bench with skopeo, which is a prerequisite of the host: %v", err)
567		}
568		// The command that `mise run nexus-bench:up` runs, built once: the lifecycle
569		// compares the descriptor.json it really writes, not one built in memory.
570		root := miseRepoRoot(t)
571		binary := filepath.Join(t.TempDir(), "nexus-bench")
572		build := exec.Command("go", "build", "-o", binary, "./internal/nexusbench/cmd/nexus-bench")
573		build.Dir = root
574		if built, err := build.CombinedOutput(); err != nil {
575			t.Fatalf("build the nexus-bench command: %v\n%s", err, built)
576		}
577		clock, prober, out := NewClock(), NewProber(), logWriter{t}
578		ctx := context.Background()
579		initial := NewKubectlInitialPassword(runner, p.Namespace)
580	
581		up := func() {
582			t.Helper()
583			if _, err := Deploy(ctx, runner, prober, clock, p, out); err != nil {
584				t.Fatalf("up: %v", err)
585			}
586			if err := EnsureUpstream(ctx, runner, clock, p, out); err != nil {
587				t.Fatalf("up, the upstream: %v", err)
588			}
589		}
590		// commandUp runs `nexus-bench up` with the descriptor written to path, and
591		// returns the bytes of that file: Deploy, the upstream, Provision, Seed.
592		commandUp := func(path string) []byte {
593			t.Helper()
594			cmd := exec.CommandContext(ctx, binary, "up")
595			cmd.Dir = root
596			cmd.Env = append(os.Environ(), envDescriptor+"="+path, envSecrets+"="+secretsPath, envAcceptEULA+"=yes")
597			cmd.Stdout, cmd.Stderr = out, out
598			if err := cmd.Run(); err != nil {
599				t.Fatalf("nexus-bench up: %v", err)
600			}
601			data, err := os.ReadFile(path)
602			if err != nil {
603				t.Fatalf("nexus-bench up wrote no descriptor: %v", err)
604			}
605			return data
606		}
607		down := func() {
608			t.Helper()
609			if err := Destroy(ctx, runner, clock, store, p, out); err != nil {
610				t.Fatalf("down: %v", err)
611			}
612			_, stderr, err := runner.Run(ctx, nil, "get", "namespace", p.Namespace)
613			if err == nil || !isNotFound(string(stderr)) {
614				t.Fatalf("after down, `get namespace %s` = (err %v), want NotFound", p.Namespace, err)
615			}
616		}
617		snapshot := func() benchSnapshot {
618			t.Helper()
619			secrets, found, err := store.Load()
620			if err != nil || !found {
621				t.Fatalf("read the secrets (found %v): %v", found, err)
622			}
623			c := newClient(RESTBaseURL(loopbackHost, p), adminUserID, secrets.AdminPassword)
624			defer c.closeIdle()
625			return snapshotBench(ctx, t, c)
626		}
627	
628		t.Log("first nexus-bench up: deploy, provision and seed")
629		descriptorPath := filepath.Join(t.TempDir(), "descriptor.json")
630		firstDescriptor := commandUp(descriptorPath)
631		desc, err := LoadDescriptor(descriptorPath)
632		if err != nil {
633			t.Fatalf("the descriptor written by up: %v", err)
634		}
635		first := snapshot()
636		for _, want := range desc.Repositories {
637			if !slices.Contains(first.Repositories, want.Name) {
638				t.Fatalf("after up the instance lists %v, want the repository %s of the descriptor", first.Repositories, want.Name)
639			}
640		}
641		// up populates: the data set is in the repositories and in the descriptor.
642		if len(desc.Dataset) != len(Dataset()) || len(first.Hosted) == 0 || len(first.Proxy) == 0 {
643			t.Fatalf("after up: %d images described, %d hosted components, %d proxy components, want the whole data set (%d images)",
644				len(desc.Dataset), len(first.Hosted), len(first.Proxy), len(Dataset()))
645		}
646	
647		t.Log("second nexus-bench up: the same descriptor.json, byte for byte, and the same components")
648		if second := commandUp(descriptorPath); !bytes.Equal(firstDescriptor, second) {
649			t.Errorf("a second up wrote another descriptor.json:\nfirst  %s\nsecond %s", firstDescriptor, second)
650		}
651		if second := snapshot(); !reflect.DeepEqual(first, second) {
652			t.Errorf("a second up changed the instance:\nfirst  %+v\nsecond %+v", first, second)
653		}
654	
655		t.Log("down")
656		down()
657	
658		t.Log("up on a fresh instance")
659		up()
660		password, ok, err := initial.Read(ctx)
661		if err != nil {
662			t.Fatalf("read the initial password: %v", err)
663		}
664		if !ok || password == "" {
665			t.Error("a fresh instance has no admin.password in the pod")
666		}
667	
668		t.Log("final down")
669		down()
670	}
