20	// The tests of this file act on the real cluster the bench runs on (datomir by
21	// default). Every one of them starts with requireBench(t), which skips unless
22	// DEVDESK_NEXUS_BENCH=1 is set and CI is empty, so `mise run test` and the CI
23	// never reach them; `mise run nexus-bench:test` sets the variable. guard_test.go
24	// fails the suite when a test of this package calls the cluster, the bench
25	// descriptor or the secrets path without that guard.
26	//
27	// What they do on the bench:
28	//
29	//   - TestIntegrationBenchDescribed, TestIntegrationAnonymousAsDescribed: read
30	//     only (GET requests as admin or without credentials).
31	//   - TestIntegrationPullAccountIsReadOnly: GET requests, plus one POST as
32	//     bench-pull that Nexus has to refuse. Should the account be allowed to
33	//     create it, the repository is deleted again (as admin) and the test fails.
34	//   - TestIntegrationDatasetAsDescribed (DEVDESK-505): read only, REST listings
35	//     of docker-hosted and docker-proxy (and, only when the listing gives no
36	//     digest, skopeo inspect of an image the descriptor says is hosted or cached).
37	//     It never reads mirror/uncached through docker-proxy or docker-group: a read
38	//     through them caches the image (F9) and only a reset undoes that.
39	//   - TestIntegrationLifecycle: destructive (up, provision, seed, up again, down,
40	//     up, down), run only with DEVDESK_NEXUS_BENCH_LIFECYCLE=1 and
41	//     NEXUS_BENCH_ACCEPT_EULA=yes. It needs skopeo on the host.
42	//
43	// None of them writes the versioned descriptor.json.
44	
45	const (
46		// benchGateEnv opens the tests that read the bench.
47		benchGateEnv = "DEVDESK_NEXUS_BENCH"
48		// benchLifecycleEnv opens, in addition, the test that destroys the bench.
49		benchLifecycleEnv = "DEVDESK_NEXUS_BENCH_LIFECYCLE"
50	
51		// liveCallTimeout bounds one group of REST calls of a read-only test.
52		liveCallTimeout = time.Minute
53		// lifecycleMinTimeout is the go test -timeout below which the lifecycle
54		// refuses to start: three deployments of up to ten minutes each, plus the
55		// deletions. The default of go test is 10 minutes.
56		lifecycleMinTimeout = 45 * time.Minute
57	
58		// readOnlyProbeRepository names the repository the read-only account is
59		// asked to create. It must never exist.
60		readOnlyProbeRepository = "bench-readonly-probe"
61	)
62	
63	// requireBench skips the test unless it may talk to the real bench: the
64	// variable DEVDESK_NEXUS_BENCH is 1 and CI is empty. The same motif as
65	// internal/nettrace/live_linux_test.go.
66	func requireBench(t *testing.T) {
67		t.Helper()
68		if os.Getenv(benchGateEnv) != "1" {
69			t.Skipf("set %s=1 to run against the real bench (it reaches the cluster)", benchGateEnv)
70		}
71		if os.Getenv("CI") != "" {
72			t.Skip("the bench tests never run in CI")
73		}
74	}
