84	// secretsPathFor is where the secrets of a bench live: NEXUS_BENCH_SECRETS when
85	// set, else the default path of the context and the namespace.
86	func secretsPathFor(t *testing.T, kubeContext, namespace string) string {
87		t.Helper()
88		requireBench(t)
89		if v := os.Getenv(envSecrets); v != "" {
90			return v
91		}
92		path, err := DefaultSecretsPath(kubeContext, namespace, os.Getenv)
93		if err != nil {
94			t.Fatalf("secrets path: %v", err)
95		}
96		return path
