99	// openLiveBench loads the descriptor and the secrets of the running bench. It
100	// writes nothing and fails with the command to run when the bench is not up.
101	func openLiveBench(t *testing.T) liveBench {
102		t.Helper()
103		requireBench(t)
104	
105		path := DescriptorPath()
106		desc, err := LoadDescriptor(path)
107		if errors.Is(err, ErrNoDescriptor) {
108			t.Fatalf("%v: bring the bench up first with `mise run nexus-bench:up`", err)
109		}
110		if err != nil {
111			t.Fatalf("LoadDescriptor(%s): %v", path, err)
112		}
113	
114		var restURL string
115		for _, raw := range desc.REST.URLs {
116			u, err := url.Parse(raw)
117			if err == nil && u.Hostname() == loopbackHost {
118				restURL = raw
119				break
120			}
121		}
122		if restURL == "" {
123			t.Fatalf("the descriptor lists no REST URL on %s (urls: %v)", loopbackHost, desc.REST.URLs)
124		}
125	
126		store, err := NewFileStore(secretsPathFor(t, desc.KubeContext, desc.Namespace))
127		if err != nil {
128			t.Fatalf("NewFileStore: %v", err)
129		}
130		secrets, found, err := store.Load()
131		if err != nil {
132			t.Fatalf("read the secrets: %v", err)
133		}
134		if !found || secrets.AdminPassword == "" {
135			t.Fatal("no admin password in the secrets file: provision the bench with `mise run nexus-bench:provision`")
136		}
137		return liveBench{desc: desc, restURL: restURL, secrets: secrets}
138	}
