158	// recycleUpstreamStorage empties the upstream registry by replacing its claim:
159	// the upstream is cut, the claim bench-upstream-data (and nothing else) is
160	// deleted once its label is checked, recreated from its manifest alone, and the
161	// upstream is brought back to one ready replica. The delete is sent once and never
162	// retried; the wait for the claim to be gone lasts until Params.DeleteTimeout.
163	// Like CutUpstream, it runs no preflight (the caller runs OpReset), refuses a
164	// custom upstream before any call, returns a cancelled context as is and accepts
165	// a nil out. A claim that is already gone is not deleted again, so a run that
166	// stopped between the delete and the apply starts again where it stopped.
167	func recycleUpstreamStorage(ctx context.Context, r Runner, clk Clock, p Params, out io.Writer) error {
168		if out == nil {
169			out = io.Discard
170		}
171		if err := validateNamespace(p.Namespace); err != nil {
172			return err
173		}
174		if err := CutUpstream(ctx, r, clk, p, out); err != nil {
175			return err
176		}
177		d := &deployer{pf: preflight{r: r, p: p}, w: upstreamWorkload(), tag: "upstream", clk: clk, out: out}
178		if err := d.deleteUpstreamClaim(ctx); err != nil {
179			return err
180		}
181		claim, err := renderUpstreamClaim(p)
182		if err != nil {
183			return err
184		}
185		d.say("creating the claim %s again", upstreamClaimName)
186		if err := d.apply(ctx, "the claim "+upstreamClaimName, claim); err != nil {
187			return err
188		}
189		return EnsureUpstream(ctx, r, clk, p, out)
190	}
191	
192	// checkedUpstreamClaim reads the claim of the upstream and checks that its label
193	// proves the bench created it; found is false when the claim is not there. It
194	// returns the UID of the claim it read.
195	func (d *deployer) checkedUpstreamClaim(ctx context.Context) (uid string, found bool, err error) {
196		uid, labels, found, err := d.readUpstreamClaim(ctx)
197		if err != nil || !found {
198			return "", found, err
199		}
200		if labels[managedByLabel] != managedByValue {
201			return "", true, &BenchError{
202				Kind:  Unclassified,
203				Cause: fmt.Sprintf("the claim %s does not carry the label %s=%s, so the bench did not create it and will not delete it", upstreamClaimName, managedByLabel, managedByValue),
204				Check: d.pf.command("get", "pvc", upstreamClaimName, "-n", d.pf.p.Namespace, "--show-labels"),
205			}
206		}
207		return uid, true, nil
208	}
209	
210	// deleteUpstreamClaim deletes the claim of the upstream, once its label proves
211	// the bench created it, and waits until it is gone. A claim that is not there is
212	// left as it is. The delete carries a precondition on the UID that was read, so a
213	// claim replaced since the read is not deleted: kubectl has no flag for it, hence
214	// the raw form with a DeleteOptions body. A claim read without a UID is refused:
215	// an empty precondition would protect nothing.
216	func (d *deployer) deleteUpstreamClaim(ctx context.Context) error {
217		if err := validateNamespace(d.pf.p.Namespace); err != nil {
218			return err
219		}
220		uid, found, err := d.checkedUpstreamClaim(ctx)
221		if err != nil || !found {
222			return err
223		}
224		if uid == "" {
225			return &BenchError{
226				Kind:  Unclassified,
227				Cause: fmt.Sprintf("kubectl returned the claim %s without a UID, so the delete cannot carry its precondition and is not sent", upstreamClaimName),
228				Check: d.pf.command("get", "pvc", upstreamClaimName, "-n", d.pf.p.Namespace, "-o", "jsonpath={.metadata.uid}"),
229			}
230		}
231		body, err := json.Marshal(map[string]any{
232			"kind":          "DeleteOptions",
233			"apiVersion":    "v1",
234			"preconditions": map[string]string{"uid": uid},
235		})
236		if err != nil {
237			return err
238		}
239		d.say("deleting the claim %s", upstreamClaimName)
240		path := "/api/v1/namespaces/" + d.pf.p.Namespace + "/persistentvolumeclaims/" + upstreamClaimName
241		args := []string{"delete", "--raw", path, "-f", "-", applyTimeout}
242		if _, errOut, err := d.pf.r.Run(ctx, body, args...); err != nil {
243			if cerr := ctx.Err(); cerr != nil {
244				return cerr
245			}
246			return d.pf.failure("delete the claim "+upstreamClaimName, args, string(errOut), err)
247		}
248		return d.waitUpstreamClaimGone(ctx)
249	}
250	
251	// readUpstreamClaim reads the claim of the upstream by name; found is false when
252	// it is not there.
253	func (d *deployer) readUpstreamClaim(ctx context.Context) (uid string, labels map[string]string, found bool, err error) {
254		var claim struct {
255			Metadata struct {
256				UID    string            `json:"uid"`
257				Labels map[string]string `json:"labels"`
258			} `json:"metadata"`
259		}
260		args := []string{"get", "pvc", upstreamClaimName, "-n", d.pf.p.Namespace, "-o", "json"}
261		found, err = d.fetch(ctx, "read the claim "+upstreamClaimName, args, &claim, true)
262		return claim.Metadata.UID, claim.Metadata.Labels, found, err
263	}
264	
265	// waitUpstreamClaimGone polls the claim until it is not there, or until
266	// Params.DeleteTimeout passes. Like the other waits, it looks at the deadline
267	// after a reading.
268	func (d *deployer) waitUpstreamClaimGone(ctx context.Context) error {
269		p := d.pf.p
270		deadline := d.clk.Now().Add(p.DeleteTimeout)
271		for {
272			_, _, found, err := d.readUpstreamClaim(ctx)
273			if err != nil || !found {
274				return err
275			}
276			if !d.clk.Now().Before(deadline) {
277				return &BenchError{
278					Kind:  Deadline,
279					Cause: fmt.Sprintf("the claim %s is still terminating after %s: a finalizer (kubernetes.io/pvc-protection) may hold it", upstreamClaimName, p.DeleteTimeout),
280					Check: d.pf.command("get", "pvc", upstreamClaimName, "-n", p.Namespace, "-o", "yaml"),
281				}
282			}
283			if err := d.clk.Sleep(ctx, upstreamPollInterval); err != nil {
284				return err
285			}
286		}
287	}
