90	// ---- guard 1: requireBench ---------------------------------------------------
91	
92	// benchGuardedCalls are the calls that reach the real bench: kubectl on PATH,
93	// the versioned descriptor that names the bench, the secrets path of the bench,
94	// and a REST client, plus the two other doors that find a binary on PATH:
95	// NewExecPortForwarder (kubectl again) and NewSkopeoCopier (skopeo, which
96	// reaches any registry its caller names). A test (or helper) that makes one has
97	// to call requireBench(t) first, unless it is an exception below.
98	var benchGuardedCalls = []string{"NewExecRunner", "NewExecPortForwarder", "NewSkopeoCopier", "DescriptorPath", "DefaultSecretsPath", "newClient"}
99	
100	// benchException is a function allowed to make a guarded call without
101	// requireBench, because what it does cannot reach the bench. check, when set,
102	// verifies the reason in the source of the function, so the exception cannot
103	// outlive it.
104	type benchException struct {
105		reason string
106		check  func(*ast.FuncDecl) string
107	}
108	
109	// requireBenchExceptions are named, never matched by pattern. TestGuardExceptionsStillMatch
110	// fails when one stops matching a function that makes a guarded call.
111	var requireBenchExceptions = map[string]benchException{
112		// DescriptorPath is only compared with a path; the file is not read.
113		"TestDescriptorPath": {reason: "compares the path, reads no file"},
114		// A pure path computation over a map standing in for the environment.
115		"TestDefaultSecretsPath": {reason: "pure path computation", check: noRealEnvironment},
116		// The client of this test is only inspected by reflection; it never sends.
117		"TestNewClientSettings": {reason: "inspects the fields of a client that sends nothing"},
118		// The four tests of NewExecRunner run against an empty PATH or a shell
119		// script standing in for kubectl (installFakeKubectl).
120		"TestNewExecRunnerKubectlMissing":         {reason: "PATH is an empty folder", check: isolatesPath},
121		"TestExecRunnerInjectsTheContext":         {reason: "PATH leads to a fake kubectl script", check: isolatesPath},
122		"TestExecRunnerKeepsBothStreamsOnFailure": {reason: "PATH leads to a fake kubectl script", check: isolatesPath},
123		"TestExecRunnerHonorsACancelledContext":   {reason: "PATH leads to a fake kubectl script", check: isolatesPath},
124		// NewExecPortForwarder and NewSkopeoCopier (DEVDESK-539): the two helpers
125		// install a stand-in tool alone on PATH (installHelperTool) and the tests
126		// call the helpers; the two "missing" tests run on an empty PATH.
127		"newHelperForwarder":                     {reason: "PATH leads to the stand-in kubectl", check: isolatesPath},
128		"newHelperSkopeo":                        {reason: "PATH leads to the stand-in skopeo", check: isolatesPath},
129		"TestNewExecPortForwarderKubectlMissing": {reason: "PATH is an empty folder", check: isolatesPath},
130		"TestNewSkopeoCopierSkopeoMissing":       {reason: "PATH is an empty folder", check: isolatesPath},
131		"TestSkopeoAgainstFakeRegistry":          {reason: "the real skopeo talks to a registry of the test process, on the loopback, with no login of the host", check: loopbackRegistryOnly},
132	}
133	
134	// callName returns the name a call is made under: f(...) or nexusbench.f(...).
135	func callName(call *ast.CallExpr) string {
136		switch fn := call.Fun.(type) {
137		case *ast.Ident:
138			return fn.Name
139		case *ast.SelectorExpr:
140			if x, ok := fn.X.(*ast.Ident); ok && x.Name == "nexusbench" {
141				return fn.Sel.Name
142			}
143		}
144		return ""
145	}
146	
147	// isHTTPTestURL tells whether e reads the address of a test server: x.URL,
148	// x.URL() or one of them followed by a path.
149	func isHTTPTestURL(e ast.Expr) bool {
150		switch x := e.(type) {
151		case *ast.SelectorExpr:
152			return x.Sel.Name == "URL"
153		case *ast.CallExpr:
154			sel, ok := x.Fun.(*ast.SelectorExpr)
155			return ok && sel.Sel.Name == "URL" && len(x.Args) == 0
156		case *ast.BinaryExpr:
157			return x.Op == token.ADD && isHTTPTestURL(x.X)
158		case *ast.ParenExpr:
159			return isHTTPTestURL(x.X)
160		}
161		return false
162	}
163	
164	// guardedCalls returns the calls under n that reach the bench. A newClient call
165	// whose URL is the address of a test server does not.
166	func guardedCalls(n ast.Node) []*ast.CallExpr {
167		var out []*ast.CallExpr
168		ast.Inspect(n, func(n ast.Node) bool {
169			call, ok := n.(*ast.CallExpr)
170			if !ok {
171				return true
172			}
173			name := callName(call)
174			if !slices.Contains(benchGuardedCalls, name) {
175				return true
176			}
177			if name == "newClient" && len(call.Args) > 0 && isHTTPTestURL(call.Args[0]) {
178				return true
179			}
180			out = append(out, call)
181			return true
182		})
183		return out
184	}
185	
186	// firstRequireBench returns the position of the first requireBench call under n.
187	func firstRequireBench(n ast.Node) (token.Pos, bool) {
188		pos, found := token.NoPos, false
189		ast.Inspect(n, func(n ast.Node) bool {
190			if call, ok := n.(*ast.CallExpr); ok && callName(call) == "requireBench" && (!found || call.Pos() < pos) {
191				pos, found = call.Pos(), true
192			}
193			return true
194		})
195		return pos, found
196	}
197	
198	// pathIsolators are the helpers that put a stand-in tool alone first on PATH.
199	var pathIsolators = []string{"installFakeKubectl", "installHelperTool"}
200	
201	// isolatesPath tells whether the function replaces PATH: installFakeKubectl(t),
202	// installHelperTool(t, ...) or t.Setenv("PATH", ...).
203	func isolatesPath(fn *ast.FuncDecl) string {
204		found := false
205		ast.Inspect(fn, func(n ast.Node) bool {
206			call, ok := n.(*ast.CallExpr)
207			if !ok {
208				return true
209			}
210			if id, ok := call.Fun.(*ast.Ident); ok && slices.Contains(pathIsolators, id.Name) {
211				found = true
212			}
213			if sel, ok := call.Fun.(*ast.SelectorExpr); ok && sel.Sel.Name == "Setenv" && len(call.Args) > 0 {
214				if lit, ok := call.Args[0].(*ast.BasicLit); ok && lit.Value == `"PATH"` {
215					found = true
216				}
217			}
218			return true
219		})
220		if !found {
221			return "it neither calls installFakeKubectl or installHelperTool nor sets PATH, so it may find the real kubectl or skopeo"
222		}
223		return ""
224	}
225	
226	// loopbackRegistryOnly tells whether a test that runs the real skopeo only talks
227	// to a registry of its own: it starts newFakeRegistry (a server of the test
228	// process, on the loopback) and moves HOME, so no login of the machine can reach
229	// skopeo and nothing can name the bench.
230	func loopbackRegistryOnly(fn *ast.FuncDecl) string {
231		registry, home := false, false
232		ast.Inspect(fn, func(n ast.Node) bool {
233			call, ok := n.(*ast.CallExpr)
234			if !ok {
235				return true
236			}
237			if id, ok := call.Fun.(*ast.Ident); ok && id.Name == "newFakeRegistry" {
238				registry = true
239			}
240			if sel, ok := call.Fun.(*ast.SelectorExpr); ok && sel.Sel.Name == "Setenv" && len(call.Args) > 0 {
241				if lit, ok := call.Args[0].(*ast.BasicLit); ok && lit.Value == `"HOME"` {
242					home = true
243				}
244			}
245			return true
246		})
247		switch {
248		case !registry:
249			return "it does not start newFakeRegistry, so nothing says which registry skopeo talks to"
250		case !home:
251			return `it does not set HOME, so skopeo may read a login of the machine`
252		}
253		return ""
254	}
255	
256	// noRealEnvironment tells whether DefaultSecretsPath is given something other
257	// than os.Getenv, so it never reads the environment of the machine.
258	func noRealEnvironment(fn *ast.FuncDecl) string {
259		problem := ""
260		ast.Inspect(fn, func(n ast.Node) bool {
261			call, ok := n.(*ast.CallExpr)
262			if !ok || callName(call) != "DefaultSecretsPath" || len(call.Args) < 3 {
263				return true
264			}
265			if sel, ok := call.Args[2].(*ast.SelectorExpr); ok {
266				if x, ok := sel.X.(*ast.Ident); ok && x.Name == "os" && sel.Sel.Name == "Getenv" {
267					problem = "DefaultSecretsPath reads the real environment (os.Getenv)"
268				}
269			}
270			return true
271		})
272		return problem
273	}
274	
275	// benchScan is what the requireBench guard found in one file.
276	type benchScan struct {
277		findings []string
278		// excepted are the exceptions this file used: a function that makes a
279		// guarded call without requireBench and is named in the exceptions.
280		excepted []string
281	}
282	
283	// scanRequireBench checks every function of src that makes a guarded call.
284	func scanRequireBench(src parsedSource, exceptions map[string]benchException) benchScan {
285		var res benchScan
286		for _, decl := range src.file.Decls {
287			calls := guardedCalls(decl)
288			if len(calls) == 0 {
289				continue
290			}
291			// Only a plain function can be an exception: a method or a variable
292			// that shares the name of one does not inherit it.
293			name, fn := "", (*ast.FuncDecl)(nil)
294			if f, ok := decl.(*ast.FuncDecl); ok && f.Recv == nil {
295				name, fn = f.Name.Name, f
296			}
297			first := calls[0]
298			if guard, ok := firstRequireBench(decl); ok && guard < first.Pos() {
299				continue
300			}
301			what := callName(first) + " reaches the bench"
302			ex, excepted := exceptions[name]
303			switch {
304			case fn == nil || !excepted:
305				where := "outside a plain function"
306				if fn != nil {
307					where = "in " + name
308				}
309				res.findings = append(res.findings, src.at(first)+": "+what+" "+where+" without a requireBench(t) call before it")
310			default:
311				if problem := ex.run(fn); problem != "" {
312					res.findings = append(res.findings, src.at(first)+": exception for "+name+" no longer holds: "+problem)
313				}
314				res.excepted = append(res.excepted, name)
315			}
316		}
317		return res
318	}
319	
320	func (e benchException) run(fn *ast.FuncDecl) string {
321		if e.check == nil {
322			return ""
323		}
324		return e.check(fn)
325	}
326	
327	// staleExceptions returns the exceptions that no function used.
328	func staleExceptions(exceptions map[string]benchException, used []string) []string {
329		var stale []string
330		for name := range exceptions {
331			if !slices.Contains(used, name) {
332				stale = append(stale, name)
333			}
334		}
335		slices.Sort(stale)
336		return stale
337	}
338	
339	// Limit (stated, not hidden): the guard reads calls by name in the test files
340	// of this folder. A guarded call hidden behind a function value, or made from
341	// the tests of cmd/nexus-bench (which run on fakes, with their own package),
342	// is not seen.
343	func scanAllRequireBench(t *testing.T) (findings, used []string) {
344		t.Helper()
345		for _, src := range packageSources(t, true, false) {
346			res := scanRequireBench(src, requireBenchExceptions)
347			findings = append(findings, res.findings...)
348			used = append(used, res.excepted...)
349		}
350		return findings, used
351	}
352	
353	func TestGuardBenchTestsCallRequireBench(t *testing.T) {
354		findings, _ := scanAllRequireBench(t)
355		for _, f := range findings {
356			t.Error(f)
357		}
358	}
