361	// calls requireBench) is a hole in waiting: it has to go.
362	func TestGuardExceptionsStillMatch(t *testing.T) {
363		_, used := scanAllRequireBench(t)
364		for _, name := range staleExceptions(requireBenchExceptions, used) {

