14	
15	const (
16		// upstreamServiceName and upstreamServicePort are the Service of the bench
17		// upstream registry and the port the port-forward reaches.
18		upstreamServiceName = upstreamDeployment
19		upstreamServicePort = 5000
20	
21		// seedListWait bounds the wait for a repository to list what the seed put in
22		// it (H-COMPONENTS), and seedListInterval separates two readings.
23		seedListWait     = 30 * time.Second
24		seedListInterval = 2 * time.Second
25	
26		// seedLoopbackHost is the only host the port-forward may be reached on.
27		seedLoopbackHost = "127.0.0.1"
28	
29		// maxSeedNamesShown bounds the names of components a message prints, the rest
30		// being summed up as "and K more" (F3 of the audit).
31		maxSeedNamesShown = 5
32	
33		// resetCheck is what a repository that holds more than the data set asks.
34		resetCheck = "run `mise run nexus-bench:reset` to bring the bench back to its initial state"
35	)
36	
37	// SeedDeps are the doors Seed goes through: the cluster (to read the upstream),
38	// the port-forward to the upstream, the image copier, the clock of the bounded
39	// wait and the stored secrets.
40	type SeedDeps struct {
41		Runner    Runner
42		Forwarder PortForwarder
43		Copier    ImageCopier
44		Clock     Clock
45		Store     SecretStore
46	}
47	
48	// SeedResult is what Seed leaves in place: the data set, every digest filled,
49	// PullThrough true exactly for the images now cached in docker-proxy.
50	type SeedResult struct{ Images []DatasetImage }
51	
52	// Seed puts the data set (D-I) in place, in this order: the stored credentials,
53	// the state of the upstream (read only), the OCI layout in a temporary folder,
54	// the port-forward to the upstream and the upstream images, the end of the
55	// port-forward, the docker-hosted images, the pull-through of the PullThrough
56	// images by docker-proxy, and the two listings, which must hold the data set and
57	// nothing else. An image is copied only when the digest read at its destination
58	// differs from the one of the data set, so a second run copies nothing.
59	//
60	// Seed never scales, applies or writes to Nexus, and it never restores a cut
61	// upstream (NX-02b): a cut, missing or starting upstream is a SeedFailed before
62	// the first copy. Docker-proxy is read only for the PullThrough images (F9): a
63	// read of mirror/uncached through it would cache it, and only reset removes
64	// that. Every failure is a *BenchError whose cause stays reachable with
65	// errors.Is and is never printed, but a cancelled context, which is returned
66	// as is. A nil out discards the progress lines ("seed: ...", no password).
67	func Seed(ctx context.Context, d SeedDeps, baseURL string, p Params, out io.Writer) (SeedResult, error) {
68		if out == nil {
69			out = io.Discard
70		}
71		if err := ctx.Err(); err != nil {
72			return SeedResult{}, err
73		}
74		admin, pull, c, err := seedCredentials(ctx, d.Store, baseURL)
75		if err != nil {
76			return SeedResult{}, err
77		}
78		defer c.closeIdle()
79		if err := requireSeedableUpstream(ctx, d.Runner, p); err != nil {
80			return SeedResult{}, err
81		}
82	
83		images := Dataset()
84		s := &seeder{ctx: ctx, d: d, p: p, out: out, c: c, baseURL: baseURL, admin: admin, pull: pull, images: images}
85		root, err := os.MkdirTemp("", "nexus-bench-seed-")
86		if err != nil {
87			return SeedResult{}, &BenchError{
88				Kind:  SeedFailed,
89				Cause: "the temporary folder of the seed cannot be created",
90				Check: "check that TMPDIR is a folder this user can write to",
91				Err:   err,
92			}
93		}
94		defer func() { _ = os.RemoveAll(root) }()
95		if err := s.writeLayout(root); err != nil {
96			return SeedResult{}, err
97		}
98		steps := []func() error{
99			s.seedUpstream,
100			s.seedHosted,
101			func() error { return s.pullThrough(root) },
102			func() error { return s.verify(dockerProxyRepository, s.wanted(isPullThrough)) },
103			func() error { return s.verify(dockerHostedRepository, s.wanted(isHosted)) },
104		}
105		for _, step := range steps {
106			if err := step(); err != nil {
107				return SeedResult{}, err
108			}
109		}
110		s.say("the data set is in place: %d images", len(images))
111		return SeedResult{Images: images}, nil
112	}
