192	// checkedUpstreamClaim reads the claim of the upstream and checks that its label
193	// proves the bench created it; found is false when the claim is not there. It
194	// returns the UID of the claim it read.
195	func (d *deployer) checkedUpstreamClaim(ctx context.Context) (uid string, found bool, err error) {
196		uid, labels, found, err := d.readUpstreamClaim(ctx)
197		if err != nil || !found {
198			return "", found, err
199		}
200		if labels[managedByLabel] != managedByValue {
201			return "", true, &BenchError{
202				Kind:  Unclassified,
203				Cause: fmt.Sprintf("the claim %s does not carry the label %s=%s, so the bench did not create it and will not delete it", upstreamClaimName, managedByLabel, managedByValue),
204				Check: d.pf.command("get", "pvc", upstreamClaimName, "-n", d.pf.p.Namespace, "--show-labels"),
205			}
206		}
207		return uid, true, nil
208	}
209	
210	// deleteUpstreamClaim deletes the claim of the upstream, once its label proves
211	// the bench created it, and waits until it is gone. A claim that is not there is
212	// left as it is. The delete carries a precondition on the UID that was read, so a
213	// claim replaced since the read is not deleted: kubectl has no flag for it, hence
214	// the raw form with a DeleteOptions body. A claim read without a UID is refused:
215	// an empty precondition would protect nothing.
216	func (d *deployer) deleteUpstreamClaim(ctx context.Context) error {
217		if err := validateNamespace(d.pf.p.Namespace); err != nil {
218			return err
219		}
220		uid, found, err := d.checkedUpstreamClaim(ctx)
221		if err != nil || !found {
222			return err
223		}
224		if uid == "" {
225			return &BenchError{
226				Kind:  Unclassified,
227				Cause: fmt.Sprintf("kubectl returned the claim %s without a UID, so the delete cannot carry its precondition and is not sent", upstreamClaimName),
228				Check: d.pf.command("get", "pvc", upstreamClaimName, "-n", d.pf.p.Namespace, "-o", "jsonpath={.metadata.uid}"),
229			}
230		}
231		body, err := json.Marshal(map[string]any{
232			"kind":          "DeleteOptions",
233			"apiVersion":    "v1",
234			"preconditions": map[string]string{"uid": uid},
235		})
236		if err != nil {
237			return err
238		}
239		d.say("deleting the claim %s", upstreamClaimName)
240		path := "/api/v1/namespaces/" + d.pf.p.Namespace + "/persistentvolumeclaims/" + upstreamClaimName
241		args := []string{"delete", "--raw", path, "-f", "-", applyTimeout}
242		if _, errOut, err := d.pf.r.Run(ctx, body, args...); err != nil {
243			if cerr := ctx.Err(); cerr != nil {
244				return cerr
245			}
246			return d.pf.failure("delete the claim "+upstreamClaimName, args, string(errOut), err)
247		}
248		return d.waitUpstreamClaimGone(ctx)
249	}
