251	// readUpstreamClaim reads the claim of the upstream by name; found is false when
252	// it is not there.
253	func (d *deployer) readUpstreamClaim(ctx context.Context) (uid string, labels map[string]string, found bool, err error) {
254		var claim struct {
255			Metadata struct {
256				UID    string            `json:"uid"`
257				Labels map[string]string `json:"labels"`
258			} `json:"metadata"`
259		}
260		args := []string{"get", "pvc", upstreamClaimName, "-n", d.pf.p.Namespace, "-o", "json"}
261		found, err = d.fetch(ctx, "read the claim "+upstreamClaimName, args, &claim, true)
262		return claim.Metadata.UID, claim.Metadata.Labels, found, err
263	}
