265	// waitUpstreamClaimGone polls the claim until it is not there, or until
266	// Params.DeleteTimeout passes. Like the other waits, it looks at the deadline
267	// after a reading.
268	func (d *deployer) waitUpstreamClaimGone(ctx context.Context) error {
269		p := d.pf.p
270		deadline := d.clk.Now().Add(p.DeleteTimeout)
271		for {
272			_, _, found, err := d.readUpstreamClaim(ctx)
273			if err != nil || !found {
274				return err
275			}
276			if !d.clk.Now().Before(deadline) {
277				return &BenchError{
278					Kind:  Deadline,
279					Cause: fmt.Sprintf("the claim %s is still terminating after %s: a finalizer (kubernetes.io/pvc-protection) may hold it", upstreamClaimName, p.DeleteTimeout),
280					Check: d.pf.command("get", "pvc", upstreamClaimName, "-n", p.Namespace, "-o", "yaml"),
281				}
282			}
283			if err := d.clk.Sleep(ctx, upstreamPollInterval); err != nil {
284				return err
285			}
286		}
287	}
